/**
 * Volunteer Survey Data Cleaner
 * Idempotent script: preserves manual edits in G2:Q (updates only blank or 'REVIEW' cells)
 * and updates a Summary sheet on each run.
 */

const RAW_SHEET = 'Raw';
const MAP_SHEET = 'ParkMap';
const PENDING_SHEET = 'ParkMapPending';
const SUMMARY_SHEET = 'Summary';
const DUP_WINDOW_MINS = 10;

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('Volunteer Data')
    .addItem('Run Cleaning Script', 'cleanVolunteerData')
    .addToUi();
}

function cleanVolunteerData() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const rawSheet = ss.getSheetByName(RAW_SHEET);

  if (!rawSheet) {
    SpreadsheetApp.getUi().alert(`Sheet "${RAW_SHEET}" not found. Please check the tab name.`);
    return;
  }

  // 1. Load or initialize ParkMap
  let mapSheet = ss.getSheetByName(MAP_SHEET);
  if (!mapSheet) {
    mapSheet = ss.insertSheet(MAP_SHEET);
    mapSheet.getRange(1, 1, 5, 2).setValues([
      ['Key', 'Canonical'],
      ['westside', 'West Side'],
      ['wside', 'West Side'],
      ['northpark', 'North Park'],
      ['northpk', 'North Park']
    ]);
  }
  const mapValues = mapSheet.getDataRange().getValues();
  const parkMap = new Map();
  for (let i = 1; i < mapValues.length; i++) {
    const key = String(mapValues[i][0]).trim().toLowerCase();
    const val = String(mapValues[i][1]).trim();
    if (key && val) parkMap.set(key, val);
  }

  // 2. Load or initialize ParkMapPending
  let pendingSheet = ss.getSheetByName(PENDING_SHEET);
  if (!pendingSheet) {
    pendingSheet = ss.insertSheet(PENDING_SHEET);
    pendingSheet.getRange(1, 1, 1, 2).setValues([['Unmapped Key', 'Sample Raw Text']]);
  }
  const pendingValues = pendingSheet.getDataRange().getValues();
  const existingPending = new Set();
  for (let i = 1; i < pendingValues.length; i++) {
    const key = String(pendingValues[i][0]).trim().toLowerCase();
    if (key) existingPending.add(key);
  }

  // 3. Read Raw Data (Columns A:F) & Existing Helper Data (Columns G:Q)
  const lastRow = rawSheet.getLastRow();
  if (lastRow < 2) return; // No data rows

  const numRows = lastRow - 1;
  const rawData = rawSheet.getRange(2, 1, numRows, 6).getValues();
  const existingHelpers = rawSheet.getRange(2, 7, numRows, 11).getValues(); // G:Q (11 cols)
  const newPendingRows = [];

  // Helper function: keep existing cell value unless it is blank or 'REVIEW'
  const resolveVal = (existingVal, computedVal) => {
    const str = String(existingVal ?? '').trim();
    if (str !== '' && str.toUpperCase() !== 'REVIEW') {
      return existingVal;
    }
    return computedVal;
  };

  // Pass 1: Normalize individual fields & respect existing manual overrides
  const parsedRows = rawData.map((row, idx) => {
    const [rawTs, rawName, rawEmail, rawYN, rawPhone, rawPark] = row;
    const existingRow = existingHelpers[idx];

    // G (idx 0): Normalize Y/N
    const ynStr = String(rawYN || '').trim().toLowerCase();
    let compYN = 'REVIEW';
    if (/^y(es)?$/.test(ynStr)) compYN = 'Yes';
    else if (/^no?$/.test(ynStr)) compYN = 'No';
    const cleanYN = resolveVal(existingRow[0], compYN);

    // H (idx 1): Copy of Raw Phone
    const rawPhoneCopy = resolveVal(existingRow[1], String(rawPhone ?? ''));

    // I (idx 2): Standardize Phone
    const phoneStr = String(rawPhone || '').trim();
    let digits = phoneStr.replace(/\D/g, '');
    if (digits.length === 11 && digits.startsWith('1')) {
      digits = digits.substring(1);
    }
    const compPhone = (digits.length === 10) ? digits : 'REVIEW';
    const cleanPhone = resolveVal(existingRow[2], compPhone);

    // J (idx 3): Standardize Timestamp
    let compTs = 'REVIEW';
    if (rawTs instanceof Date && !isNaN(rawTs.getTime())) {
      compTs = rawTs;
    } else if (String(rawTs || '').trim() !== '') {
      const parsedDate = new Date(String(rawTs).trim());
      if (!isNaN(parsedDate.getTime())) {
        compTs = parsedDate;
      }
    }
    const cleanTs = resolveVal(existingRow[3], compTs);

    // Extract millisecond timestamp from the resolved timestamp (supports manual date fixes)
    let tsMs = null;
    if (cleanTs instanceof Date && !isNaN(cleanTs.getTime())) {
      tsMs = cleanTs.getTime();
    } else if (String(cleanTs).trim() !== '' && String(cleanTs).toUpperCase() !== 'REVIEW') {
      const d = new Date(String(cleanTs).trim());
      if (!isNaN(d.getTime())) tsMs = d.getTime();
    }

    // K (idx 4): Consolidate Park Names
    const parkStr = String(rawPark || '').trim();
    const parkKey = parkStr.toLowerCase().replace(/[^a-z]/g, '');
    let compPark = 'REVIEW';

    if (parkKey) {
      if (parkMap.has(parkKey)) {
        compPark = parkMap.get(parkKey);
      } else if (!existingPending.has(parkKey)) {
        existingPending.add(parkKey);
        newPendingRows.push([parkKey, parkStr]);
      }
    }
    const cleanPark = resolveVal(existingRow[4], compPark);

    // L & M (idx 5 & 6): Helper Keys
    const compEmailKey = String(rawEmail || '').trim().toLowerCase();
    const compNameKey = String(rawName || '').trim().toLowerCase().replace(/\s+/g, ' ');
    const emailKey = String(resolveVal(existingRow[5], compEmailKey)).trim().toLowerCase();
    const nameKey = String(resolveVal(existingRow[6], compNameKey)).trim().toLowerCase();

    return {
      idx,
      existingRow,
      cleanYN,
      rawPhoneCopy,
      cleanPhone,
      cleanTs,
      tsMs,
      cleanPark,
      emailKey,
      nameKey
    };
  });

  // Pass 2: Evaluate Duplicates & Final Review Flag
  const emailCounts = new Map();
  const minEmailTs = new Map();

  // Gather counts and EARLIEST timestamp per email
  parsedRows.forEach(r => {
    if (r.emailKey) {
      emailCounts.set(r.emailKey, (emailCounts.get(r.emailKey) || 0) + 1);
      if (r.tsMs !== null) {
        const currentMin = minEmailTs.get(r.emailKey);
        if (currentMin === undefined || r.tsMs < currentMin) {
          minEmailTs.set(r.emailKey, r.tsMs);
        }
      }
    }
  });

  const windowMs = DUP_WINDOW_MINS * 60 * 1000;

  // Counters for Summary Sheet
  let countOK = 0;
  let countReview = 0;
  let countDupEmail = 0;
  let countDupNameTime = 0;
  let countSuperseded = 0;

  // Build final output array for Columns G:Q (11 columns)
  const outputRows = parsedRows.map((r, i) => {
    const existingRow = r.existingRow;

    // N (idx 7): DUP-email
    const compDupEmail = (r.emailKey && emailCounts.get(r.emailKey) > 1) ? 'DUP-email' : '';
    const dupEmail = resolveVal(existingRow[7], compDupEmail);

    // O (idx 8): DUP-name-time (same name within 10 mins)
    let compDupNameTime = '';
    if (r.nameKey && r.tsMs !== null) {
      const hasNearMatch = parsedRows.some((other, j) => 
        i !== j && 
        other.nameKey === r.nameKey && 
        other.tsMs !== null && 
        Math.abs(r.tsMs - other.tsMs) <= windowMs
      );
      if (hasNearMatch) compDupNameTime = 'DUP-name-time';
    }
    const dupNameTime = resolveVal(existingRow[8], compDupNameTime);

    // P (idx 9): SUPERSEDED (keep earliest per email; mark later ones SUPERSEDED)
    let compSuperseded = '';
    if (r.emailKey && emailCounts.get(r.emailKey) > 1 && r.tsMs !== null) {
      const minTs = minEmailTs.get(r.emailKey);
      if (r.tsMs > minTs) {
        compSuperseded = 'SUPERSEDED';
      } else if (r.tsMs === minTs) {
        const hasEarlierRowWithSameMinTs = parsedRows.some((other, j) => 
          j < i && other.emailKey === r.emailKey && other.tsMs === minTs
        );
        if (hasEarlierRowWithSameMinTs) compSuperseded = 'SUPERSEDED';
      }
    }
    const superseded = resolveVal(existingRow[9], compSuperseded);

    // Q (idx 10): Master Review Flag
    const needsReview = (
      String(r.cleanYN).toUpperCase() === 'REVIEW' ||
      String(r.cleanPhone).toUpperCase() === 'REVIEW' ||
      String(r.cleanTs).toUpperCase() === 'REVIEW' ||
      String(r.cleanPark).toUpperCase() === 'REVIEW' ||
      String(dupEmail) !== '' ||
      String(dupNameTime) !== ''
    );
    const compReviewFlag = needsReview ? 'REVIEW' : 'OK';
    const reviewFlag = resolveVal(existingRow[10], compReviewFlag);

    // Tally summary counts
    if (String(reviewFlag).toUpperCase() === 'OK') countOK++;
    if (String(reviewFlag).toUpperCase() === 'REVIEW') countReview++;
    if (String(dupEmail) !== '') countDupEmail++;
    if (String(dupNameTime) !== '') countDupNameTime++;
    if (String(superseded) !== '') countSuperseded++;

    return [
      r.cleanYN,      // G
      r.rawPhoneCopy, // H (Raw Phone Copy)
      r.cleanPhone,   // I (Standardized Phone)
      r.cleanTs,      // J
      r.cleanPark,    // K
      r.emailKey,     // L
      r.nameKey,      // M
      dupEmail,       // N
      dupNameTime,    // O
      superseded,     // P
      reviewFlag      // Q
    ];
  });

  // 4. Write Headers (only if missing) and Data to Raw Sheet (Columns G:Q)
  const defaultHeaders = [
    'Clean_YN', 'Raw_Phone_Copy', 'Clean_Phone', 'Clean_Timestamp', 'Clean_Park', 
    'Key_Email', 'Key_Name', 'Flag_DupEmail', 'Flag_DupNameTime', 
    'Flag_Superseded', 'Review_Status'
  ];

  const headerRange = rawSheet.getRange(1, 7, 1, 11);
  const existingHeaders = headerRange.getValues()[0];
  let headersUpdated = false;

  const mergedHeaders = existingHeaders.map((cellVal, idx) => {
    if (String(cellVal).trim() === '') {
      headersUpdated = true;
      return defaultHeaders[idx];
    }
    return cellVal;
  });

  if (headersUpdated) {
    headerRange.setValues([mergedHeaders]).setFontWeight('bold');
  }

  // Format Raw_Phone_Copy (H, col 8) and Clean_Phone (I, col 9) as Plain Text, and Timestamp (J, col 10) as datetime
  rawSheet.getRange(2, 8, outputRows.length, 2).setNumberFormat('@');
  rawSheet.getRange(2, 10, outputRows.length, 1).setNumberFormat('yyyy-mm-dd hh:mm');

  // Write all helper columns at once
  rawSheet.getRange(2, 7, outputRows.length, 11).setValues(outputRows);

  // 5. Append any newly discovered unmapped parks to ParkMapPending
  if (newPendingRows.length > 0) {
    const nextPendingRow = pendingSheet.getLastRow() + 1;
    pendingSheet.getRange(nextPendingRow, 1, newPendingRows.length, 2).setValues(newPendingRows);
  }

  // 6. Create or Update Summary Sheet (Idempotent overwrite)
  let summarySheet = ss.getSheetByName(SUMMARY_SHEET);
  if (!summarySheet) {
    summarySheet = ss.insertSheet(SUMMARY_SHEET);
  }

  const summaryData = [
    ['Metric', 'Value'],
    ['Last Run Timestamp', new Date()],
    ['Total rows processed', outputRows.length],
    ['Count OK', countOK],
    ['Count REVIEW', countReview],
    ['Count DUP-email', countDupEmail],
    ['Count DUP-name-time', countDupNameTime],
    ['Count SUPERSEDED', countSuperseded],
    ['New unmapped parks added this run', newPendingRows.length]
  ];

  summarySheet.getRange(1, 1, summaryData.length, 2).setValues(summaryData);
  summarySheet.getRange(1, 1, 1, 2).setFontWeight('bold');
  summarySheet.getRange(2, 2).setNumberFormat('yyyy-mm-dd hh:mm:ss');
  summarySheet.autoResizeColumns(1, 2);

  SpreadsheetApp.flush();
  SpreadsheetApp.getUi().alert(
    `Cleaning complete!\n\n` +
    `Rows processed: ${outputRows.length}\n` +
    `OK: ${countOK} | REVIEW: ${countReview}\n` +
    `New unmapped parks added to ${PENDING_SHEET}: ${newPendingRows.length}`
  );
}
