```javascript
/**
 * VOLUNTEER SURVEY CLEANER
 * Reads : "Raw" (A:F = Timestamp, Name, Email, JoinedBefore, Phone, PreferredPark)
 *         "ParkMap" (A = Key [lowercase letters only], B = Canonical name)
 * Writes: "Clean" (created if missing, overwritten every run)
 * Clean columns: A Timestamp | B Name | C Email | D JoinedBefore | E Phone (10 digits) |
 *                F PreferredPark | G SUPERSEDED | H DuplicateFlag | I Review | J RawRow
 */
const RAW_SHEET = 'Raw', MAP_SHEET = 'ParkMap', CLEAN_SHEET = 'Clean';
const DUP_WINDOW_MINUTES = 10;
const REVIEW = 'REVIEW';

// Optional time part: " 09:12", " 9:12:30", " 9:12 PM", "T09:12"  (4 capture groups)
const TIME_PART = '(?:[ T,]+(\\d{1,2}):(\\d{2})(?::(\\d{2}))?\\s*([AaPp][Mm])?)?';
const RE_MDY   = new RegExp('^(\\d{1,2})[\\/\\-.](\\d{1,2})[\\/\\-.](\\d{2}|\\d{4})' + TIME_PART + '$'); // US: month first
const RE_DMONY = new RegExp('^(\\d{1,2})[\\-\\/ ]([A-Za-z]{3,9})\\.?[\\-\\/ ,]+(\\d{2}|\\d{4})' + TIME_PART + '$'); // 03-Mar-2021
const RE_ISO   = new RegExp('^(\\d{4})-(\\d{1,2})-(\\d{1,2})' + TIME_PART + '$');
const MONTHS = {jan:1,feb:2,mar:3,apr:4,may:5,jun:6,jul:7,aug:8,sep:9,oct:10,nov:11,dec:12};

function cleanSurvey() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const raw = ss.getSheetByName(RAW_SHEET);
  const mapSheet = ss.getSheetByName(MAP_SHEET);
  if (!raw) throw new Error('Sheet "' + RAW_SHEET + '" not found.');
  if (!mapSheet) throw new Error('Sheet "' + MAP_SHEET + '" not found.');
  const lastRow = raw.getLastRow();
  if (lastRow < 2) throw new Error('Raw has no data rows.');

  const data = raw.getRange(2, 1, lastRow - 1, 6).getValues();  // one bulk read
  const parkMap = loadParkMap_(mapSheet);

  // ---- Pass 1: normalize each row ----
  const recs = [];
  data.forEach(function (row, i) {
    if (row.every(function (c) { return String(c).trim() === ''; })) return; // skip blank rows
    const ts = parseTimestamp_(row[0]);
    const r = {
      rawRow: i + 2,
      ts: ts,
      time: ts ? ts.getTime() : -Infinity,         // unparsed dates count as "oldest"
      name: String(row[1]),
      nameKey: String(row[1]).toLowerCase().replace(/\s+/g, ' ').trim(),
      email: String(row[2]).trim().toLowerCase(),
      joined: normalizeYesNo_(row[3]),
      phone: normalizePhone_(row[4]),
      park: mapPark_(row[5], parkMap),
      superseded: false, dupEmail: false, dupNameTime: false, partners: []
    };
    r.sig = [r.joined, r.phone, r.park].join('|'); // "answers" signature for comparing duplicates
    recs.push(r);
  });
  if (recs.length === 0) throw new Error('Raw has no non-blank data rows.');

  // ---- Pass 2: same email -> keep most recent; tie -> keep the lower row ----
  const byEmail = groupBy_(recs, function (r) { return r.email; });
  Object.keys(byEmail).forEach(function (k) {
    const g = byEmail[k];
    if (g.length < 2) return;
    let winner = g[0];
    g.forEach(function (r) {
      if (r.time > winner.time || (r.time === winner.time && r.rawRow > winner.rawRow)) winner = r;
    });
    g.forEach(function (r) {
      r.dupEmail = true;
      if (r !== winner) r.superseded = true;
      g.forEach(function (o) { if (o !== r) r.partners.push(o); });
    });
  });

  // ---- Pass 3: same name within N minutes (flag only, no SUPERSEDED) ----
  const byName = groupBy_(recs, function (r) { return r.nameKey; });
  const windowMs = DUP_WINDOW_MINUTES * 60000;
  Object.keys(byName).forEach(function (k) {
    const g = byName[k];
    for (let a = 0; a < g.length; a++) {
      for (let b = a + 1; b < g.length; b++) {
        if (g[a].ts && g[b].ts && Math.abs(g[a].time - g[b].time) <= windowMs) {
          g[a].dupNameTime = g[b].dupNameTime = true;
          g[a].partners.push(g[b]); g[b].partners.push(g[a]);
        }
      }
    }
  });

  // ---- Pass 4: review reasons + output ----
  const out = [['Timestamp','Name','Email','JoinedBefore','Phone (10 digits)','PreferredPark',
                'SUPERSEDED','DuplicateFlag','Review','RawRow']];
  const reviewRows = [];
  recs.forEach(function (r) {
    const why = [];
    if (!r.ts) why.push('Timestamp');
    if (r.joined === REVIEW) why.push('JoinedBefore');
    if (r.phone === REVIEW) why.push('Phone');
    if (r.park === REVIEW) why.push('Park');
    // Duplicate candidates only need review if the answers differ between copies
    if (r.partners.some(function (o) { return o.sig !== r.sig; })) why.push('Duplicate with different answers');
    // No email, and the name matches another row
    if (!r.email && r.nameKey && byName[r.nameKey] && byName[r.nameKey].length > 1) why.push('No email, name matches other row');

    const flags = [];
    if (r.dupEmail) flags.push('DUP-email');
    if (r.dupNameTime) flags.push('DUP-name-time');
    out.push([r.ts || REVIEW, r.name, r.email, r.joined, r.phone, r.park,
              r.superseded ? 'SUPERSEDED' : '', flags.join(', '),
              why.length ? 'REVIEW: ' + why.join('; ') : 'OK', r.rawRow]);
    if (why.length) reviewRows.push(out.length);   // sheet row number in Clean
  });

  // ---- Write Clean ----
  const clean = ss.getSheetByName(CLEAN_SHEET) || ss.insertSheet(CLEAN_SHEET);
  clean.clear();
  const n = out.length;
  const cols = out[0].length;
  clean.getRange(1, 5, n, 1).setNumberFormat('@');                  // Phone column = plain text (set BEFORE writing values)
  clean.getRange(1, 1, n, cols).setValues(out);
  clean.getRange(2, 1, n - 1, 1).setNumberFormat('yyyy-mm-dd hh:mm'); // Timestamp as date-time
  clean.getRange(1, 1, 1, cols).setFontWeight('bold');
  clean.setFrozenRows(1);
  reviewRows.forEach(function (row) {
    clean.getRange(row, 1, 1, cols).setBackground('#fff2cc');
  });
  clean.autoResizeColumns(1, cols);

  SpreadsheetApp.getActive().toast(
    (n - 1) + ' rows cleaned, ' + reviewRows.length + ' need review, ' +
    recs.filter(function (r) { return r.superseded; }).length + ' superseded.', 'Done', 10);
}

// ---------- Helpers ----------
function groupBy_(arr, keyFn) {
  const o = Object.create(null);
  arr.forEach(function (r) {
    const k = keyFn(r);
    if (!k) return;                       // blank keys never group
    (o[k] = o[k] || []).push(r);
  });
  return o;
}

function normalizeYesNo_(v) {
  const s = String(v).trim().toLowerCase().replace(/[.!]/g, '');
  if (/^y(es)?$/.test(s)) return 'Yes';
  if (/^no?$/.test(s)) return 'No';
  return REVIEW;
}

function normalizePhone_(v) {
  let d = String(v).replace(/\D/g, '');
  if (d.length === 11 && d.charAt(0) === '1') d = d.slice(1);
  return d.length === 10 ? d : REVIEW;    // 7-digit numbers land here
}

function parkKey_(v) { return String(v).toLowerCase().replace(/[^a-z]/g, ''); }

function loadParkMap_(sheet) {
  const map = Object.create(null);
  const last = sheet.getLastRow();
  if (last < 2) return map;
  sheet.getRange(2, 1, last - 1, 2).getValues().forEach(function (r) {
    const k = parkKey_(r[0]);
    if (k && String(r[1]).trim()) map[k] = String(r[1]).trim();  // re-clean key in case it was typed loosely
  });
  return map;
}

function mapPark_(v, map) {
  const k = parkKey_(v);
  return (k && map[k]) ? map[k] : REVIEW;
}

/** Returns a Date, or null if it can't be parsed. Handles Date objects and common text formats. */
function parseTimestamp_(v) {
  if (v instanceof Date) return isNaN(v.getTime()) ? null : v;
  const s = String(v).trim();
  if (!s) return null;
  let m, y, mo, d, yStr;
  if ((m = s.match(RE_ISO)))        { yStr = m[1]; mo = +m[2]; d = +m[3]; }
  else if ((m = s.match(RE_MDY)))   { mo = +m[1]; d = +m[2]; yStr = m[3]; }
  else if ((m = s.match(RE_DMONY))) { d = +m[1]; mo = MONTHS[m[2].slice(0, 3).toLowerCase()]; yStr = m[3]; }
  else return null;
  if (!mo) return null;
  y = +yStr; if (yStr.length === 2) y += 2000;
  let hh = +m[4] || 0; const mi = +m[5] || 0, ss = +m[6] || 0, ap = m[7];
  if (ap) {
    const pm = ap.toLowerCase() === 'pm';
    if (pm && hh < 12) hh += 12;
    if (!pm && hh === 12) hh = 0;
  }
  if (hh > 23 || mi > 59 || ss > 59) return null;
  const dt = new Date(y, mo - 1, d, hh, mi, ss);
  // Reject impossible dates like 2/31 that JS would silently roll over
  return (dt.getMonth() === mo - 1 && dt.getDate() === d) ? dt : null;
}
