/* ═══════════════════════════════════════════════════════════
   SUPERSEDED COMPARISON
   ═══════════════════════════════════════════════════════════ */

/**
 * Returns true when candidate should be kept over current best.
 *
 *  1) Valid timestamp beats invalid.
 *  2) Among two valid timestamps that differ:
 *       keepFirst → earlier wins, else later wins.
 *  3) Tie or both invalid → row index breaks tie
 *       (lower idx = earlier row in sheet).
 */
function isBetter_(results, cand, best, keepFirst) {
  var cTS = results[cand][2];
  var bTS = results[best][2];
  var cOk = cTS instanceof Date;
  var bOk = bTS instanceof Date;

  if ( cOk && !bOk) return true;
  if (!cOk &&  bOk) return false;

  if (cOk && bOk) {
    var cMs = cTS.getTime(), bMs = bTS.getTime();
    if (cMs !== bMs) {
      return keepFirst ? cMs < bMs : cMs > bMs;
    }
  }
  // Tied timestamps or both invalid → row position
  return keepFirst ? cand < best : cand > best;
}


