function buildParkMapKeys() {
  var ss  = SpreadsheetApp.getActiveSpreadsheet();
  var raw = ss.getSheetByName("Raw");
  if (!raw) { alert_("Sheet 'Raw' not found."); return; }

  var pm = ss.getSheetByName("ParkMap");
  if (!pm) {
    pm = ss.insertSheet("ParkMap");
    pm.getRange(1, 1, 1, 2).setValues([["Key", "Canonical"]]);
  }

  // All keys already in ParkMap (regardless of whether
  // canonical is filled in), so we never re-add one.
  var existing = loadParkMapKeys_(ss);

  var parks  = raw.getRange(2, 6, raw.getLastRow() - 1, 1).getValues();
  var unseen = {};   // key → first raw example

  for (var i = 0; i < parks.length; i++) {
    var val = str_(parks[i][0]);
    if (val === "") continue;
    var key = val.replace(/[^a-zA-Z]/g, "").toLowerCase();
    if (key === "" || existing[key] || unseen[key]) continue;
    unseen[key] = val;
  }

  var keys = Object.keys(unseen);
  if (keys.length === 0) {
    alert_("No new park variants — ParkMap is up to date.");
    return;
  }

  var rows = keys.map(function(k) { return [k, unseen[k]]; });
  var next = pm.getLastRow() + 1;
  pm.getRange(next, 1, rows.length, 2).setValues(rows);

  alert_(keys.length + " new key(s) added to ParkMap.\n" +
         "Col B shows a raw example — overwrite it with the " +
         "canonical name, then run Full Clean again.");
}


