function normaliseYN_(val) {
  if (val === "") return "REVIEW";
  var v = val.toLowerCase();
  if (/^y(es)?$/.test(v)) return "Yes";
  if (/^no?$/.test(v))    return "No";
  return "REVIEW";
}

/** Digits only, drop leading 1 for 11-digit numbers → 10 digits or "REVIEW". */
function normalisePhone_(val) {
  if (val === "") return "REVIEW";
  var d = String(val).replace(/\D/g, "");
  if (d.length === 11 && d.charAt(0) === "1") d = d.substring(1);
  return d.length === 10 ? d : "REVIEW";
}

/**
 * Parse a timestamp into a JS Date.
 *
 * Handles three cases:
 *   1. Already a Date object (Sheets recognised the cell as a date).
 *   2. A number — Sheets serial date (days since 1899-12-30).
 *      Uses the UTC epoch offset: (serial − 25569) × 86 400 000 ms.
 *   3. A string — tries Date.parse().
 *
 * Returns a Date on success, the string "REVIEW" on failure.
 */
function normaliseTimestamp_(val) {
  // Case 1: already a Date
  if (val instanceof Date) {
    return isNaN(val.getTime()) ? "REVIEW" : val;
  }

  // Case 2: Sheets serial number
  if (typeof val === "number") {
    // Sheets serial: 1 = 1900-01-01.  JS epoch anchor: 25569 = 1970-01-01.
    var ms = (val - 25569) * 86400000;
    var d  = new Date(ms);
    return isNaN(d.getTime()) ? "REVIEW" : d;
  }

  // Case 3: string
  if (typeof val === "string" && val.trim() !== "") {
    var ms2 = Date.parse(val.trim());
    if (!isNaN(ms2)) return new Date(ms2);
  }

```javascript
/**
 * Volunteer Survey Cleaner v5
 * Run: cleanAndConsolidate()
 */

const DRY_RUN = false;
const NAME_WINDOW_MIN = 10;
const KEEP_FIRST = true;

function cleanAndConsolidate() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  const raw = ss.getSheetByName("Raw");
  if (!raw) throw new Error("Sheet 'Raw' not found");
  const data = raw.getDataRange().getValues();
  const headers = data[0];
  const colIdx = {};
  headers.forEach((h, i) => colIdx[h.toString().trim()] = i);

  const C = {
    ts: colIdx["Timestamp"], name: colIdx["Name"], email: colIdx["Email"],
    yesno: colIdx["JoinedBefore"], phone: colIdx["Phone"], park: colIdx["PreferredPark"]
  };

  const pmSheet = ss.getSheetByName("ParkMap");
  if (!pmSheet) throw new Error("Sheet 'ParkMap' not found");
  const parkMap = {};
  pmSheet.getDataRange().getValues().forEach(r => {
    if (r[0] !== "") parkMap[String(r[0]).toLowerCase().replace(/[^a-z]/g, "")] = r[1];
  });

  // ── Helpers ──

  function cleanPhone(val) {
    if (val == null || String(val).trim() === "") return "";
    let d = String(val).replace(/\D/g, "");
    if (d.length === 11 && d[0] === "1") d = d.slice(1);
    return d.length === 10 ? d : "REVIEW";
  }

  function fmtPhone(val) {
    if (!val || val === "REVIEW") return val || "";
    return "(" + val.slice(0, 3) + ") " + val.slice(3, 6) + "-" + val.slice(6);
  }

  function cleanTimestamp(val) {
    if (val instanceof Date && !isNaN(val)) return val;
    if (val == null || String(val).trim() === "") return null;
    const d = new Date(String(val));
    return isNaN(d) ? null : d;
  }

  function cleanYesNo(val) {
    const v = String(val).trim().toLowerCase();
    if (/^y(es)?$/.test(v)) return "Yes";
    if (/^no?$/.test(v)) return "No";
    return v === "" ? "" : "REVIEW";
  }

  function cleanPark(val) {
    if (val == null || String(val).trim() === "") return "";
    const key = String(val).toLowerCase().replace(/[^a-z]/g, "");
    return parkMap[key] || "REVIEW";
  }

  function normName(val) {
    return String(val || "").trim().toLowerCase().replace(/\./g, "").replace(/\s+/g, " ");
  }

  // ── Clean rows ──
  const rows = [];
  for (let i = 1; i < data.length; i++) {
    const r = data[i];
    const ts = cleanTimestamp(r[C.ts]);
    const phone = cleanPhone(r[C.phone]);
    const yesno = cleanYesNo(r[C.yesno]);
    const park = cleanPark(r[C.park]);
    const email = String(r[C.email] || "").trim().toLowerCase();
    const name = String(r[C.name] || "").trim();

    const issues = [];
    if (ts === null && String(r[C.ts]).trim() !== "") issues.push("bad-timestamp");
    if (phone === "REVIEW") issues.push("bad-phone");
    if (yesno === "REVIEW") issues.push("bad-yesno");
    if (park === "REVIEW")  issues.push("unmapped-park");
    if (email === "")       issues.push("no-email");

    rows.push({
      srcRow: i + 1, ts, name, email, yesno, phone, park, issues,
      normName: normName(name),
      rawStr: r.map(c => c instanceof Date
        ? Utilities.formatDate(c, ss.getSpreadsheetTimeZone(), "yyyy-MM-dd HH:mm")
        : String(c)).join(" | ")
    });
  }

  // ── Merge helper ──
  function mergeGroup(group, matchType) {
    group.sort((a, b) => {
      const tA = a.ts ? a.ts.getTime() : null;
      const tB = b.ts ? b.ts.getTime() : null;
      if (tA === null && tB === null) return a.srcRow - b.srcRow;
      if (tA === null) return 1;
      if (tB === null) return -1;
      const cmp = KEEP_FIRST ? (tA - tB) : (tB - tA);
      return cmp !== 0 ? cmp : (a.srcRow - b.srcRow);
    });

    const best = Object.assign({}, group[0]);
    best.srcRows = group.map(r => r.srcRow);
    best.merged = group.length > 1;
    best.matchType = matchType;
    best.rawStrs = group.map(r => "Row " + r.srcRow + ": " + r.rawStr);

    const allIssues = new Set(best.issues);
    const issueMap = {
      phone: "bad-phone", yesno: "bad-yesno",
      park: "unmapped-park", email: "no-email"
    };

    for (let i = 1; i < group.length; i++) {
      group[i].issues.forEach(iss => allIssues.add(iss));
      ["name", "phone", "yesno", "park", "email"].forEach(f => {
        if ((best[f] === "" || best[f] === "REVIEW") &&
            group[i][f] !== "" && group[i][f] !== "REVIEW") {
          best[f] = group[i][f];
          if (issueMap[f]) allIssues.delete(issueMap[f]);
        }
      });
      if (best.ts === null && group[i].ts !== null) {
        best.ts = group[i].ts;
        allIssues.delete("bad-timestamp");
      }
    }

    best.issues = [...allIssues];
    best.keepReason = best.merged
      ? (KEEP_FIRST ? "kept-earliest" : "kept-latest")
      : "single-row";
    return best;
  }

  // ── Phase 1: Group by email ──
  const byEmail = {};
  const ungrouped = [];
  rows.forEach(r => {
    if (r.email === "") { ungrouped.push(r); return; }
    (byEmail[r.email] = byEmail[r.email] || []).push(r);
  });

  const output = [];
  Object.values(byEmail).forEach(g => output.push(mergeGroup(g, "email")));

  // ── Phase 2: Name+timestamp on remaining rows ──
  const parent = ungrouped.map((_, i) => i);
  function find(x) { return parent[x] === x ? x : (parent[x] = find(parent[x])); }
  function union(a, b) { parent[find(a)] = find(b); }

  const windowMs = NAME_WINDOW_MIN * 60 * 1000;
  const nameIdx = {};
  ungrouped.forEach((r, i) => {
    if (r.normName === "") return;
    (nameIdx[r.normName] = nameIdx[r.normName] || []).push(i);
  });
  Object.values(nameIdx).forEach(idxs => {
    for (let a = 0; a < idxs.length; a++)
      for (let b = a + 1; b < idxs.length; b++) {
        const tA = ungrouped[idxs[a]].ts, tB = ungrouped[idxs[b]].ts;
        if (tA && tB && Math.abs(tA.getTime() - tB.getTime()) <= windowMs)
          union(idxs[a], idxs[b]);
      }
  });

  const clusters = {};
  ungrouped.forEach((_, i) => {
    const root = find(i);
    (clusters[root] = clusters[root] || []).push(ungrouped[i]);
  });
  Object.values(clusters).forEach(g =>
    output.push(mergeGroup(g, g.length > 1 ? "name-time" : "none"))
  );

  output.sort((a, b) => ((a.ts ? a.ts.getTime() : 0) - (b.ts ? b.ts.getTime() : 0)));

  output.forEach(r => {
    r.status = r.issues.length > 0 ? "REVIEW" : (r.merged ? "MERGED" : "KEPT");
  });

  // ── Build output ──
  const outHeaders = [
    "Timestamp", "Name", "Email", "JoinedBefore", "Phone", "PreferredPark",
    "SourceRows", "MatchType", "KeepReason", "Status", "Issues", "RawValues"
  ];

  const outData = output.map(r => [
    r.ts || "", r.name, r.email, r.yesno,
    fmtPhone(r.phone), r.park,
    r.srcRows.join(", "), r.matchType, r.keepReason,
    r.status, r.issues.join("; "), r.rawStrs.join("\n")
  ]);

  // ── Counts for summary ──
  const totalRaw = data.length - 1;  // exclude header
  const consolidated = outData.length;
  const counts = { KEPT: 0, MERGED: 0, REVIEW: 0 };
  output.forEach(r => counts[r.status]++);

  // ── Write or log ──
  if (DRY_RUN) {
    Logger.log("DRY RUN | Raw: " + totalRaw + " | Consolidated: " + consolidated +
      " | KEPT: " + counts.KEPT + " | MERGED: " + counts.MERGED +
      " | REVIEW: " + counts.REVIEW);
    outData.slice(0, 25).forEach(row => Logger.log(row.join(" | ")));
    if (outData.length > 25) Logger.log("... (" + (outData.length - 25) + " more)");
  } else {
    // -- Consolidated-preview sheet --
    let prev = ss.getSheetByName("Consolidated-preview");
    if (prev) ss.deleteSheet(prev);
    prev = ss.insertSheet("Consolidated-preview");
    prev.appendRow(outHeaders);
    if (outData.length) {
      prev.getRange(2, 1, outData.length, outHeaders.length).setValues(outData);
    }
    prev.getRange(2, 1, Math.max(outData.length, 1), 1)
        .setNumberFormat("yyyy-mm-dd hh:mm");
    prev.getRange(2, 5, Math.max(outData.length, 1), 1)
        .setNumberFormat("@");
    prev.getRange(2, outHeaders.length, Math.max(outData.length, 1), 1)
        .setWrapStrategy(SpreadsheetApp.WrapStrategy.WRAP);
    outHeaders.forEach((_, i) => prev.autoResizeColumn(i + 1));

    // -- Consolidation-Summary sheet --
    let sumSheet = ss.getSheetByName("Consolidation-Summary");
    if (sumSheet) ss.deleteSheet(sumSheet);
    sumSheet = ss.insertSheet("Consolidation-Summary");
    sumSheet.getRange(1, 1, 6, 2).setValues([
      ["Metric",            "Count"],
      ["Total raw rows",    totalRaw],
      ["Consolidated rows", consolidated],
      ["KEPT",              counts.KEPT],
      ["MERGED",            counts.MERGED],
      ["REVIEW",            counts.REVIEW]
    ]);
    sumSheet.getRange(1, 1, 1, 2).setFontWeight("bold");
    sumSheet.autoResizeColumn(1);
    sumSheet.autoResizeColumn(2);

    Logger.log("Done | Raw: " + totalRaw + " → Consolidated: " + consolidated +
      " (KEPT: " + counts.KEPT + ", MERGED: " + counts.MERGED +
      ", REVIEW: " + counts.REVIEW + ")");
  }
}

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu("🧹 Cleaning")
    .addItem("Run consolidation", "cleanAndConsolidate")
    .addToUi();
}
