    joinedBefore:  6,  // G - cleaned Yes/No
    phone:         7,  // H - cleaned phone
    timestamp_c:   8,  // I - cleaned timestamp
    park:          9,  // J - cleaned park
    reviewFlag:   15,  // P - review flag (0-based = col 16)
  };

  // Output columns (0-based). These will be written or created.
  const OUT = {
    cleanedJoined:    16,  // Q
    cleanedPhone:     17,  // R
    cleanedTimestamp: 18,  // S
    cleanedPark:      19,  // T
    superseded:       20,  // U
    conflicts:        21,  // V
  };

  const HEADER_ROW = 0;
  const headers = data[HEADER_ROW];

  // Write output headers if the row is the header row.
  const outputHeaders = ["CleanedJoined", "CleanedPhone", "CleanedTimestamp", "CleanedPark", "Superseded", "Conflicts"];
  outputHeaders.forEach((h, i) => {
    sheet.getRange(1, OUT.cleanedJoined + i + 1).setValue(h);
  });

  // ── Helpers ──────────────────────────────────────────────────────────────

  function normalizePhone(raw) {
    if (!raw) return "";
    const digits = raw.toString().replace(/\D/g, "");
    if (digits.length === 10) return digits;
    if (digits.length === 11 && digits[0] === "1") return digits.slice(1);
    if (digits.length === 7 && defaultAreaCode.length === 3) return defaultAreaCode + digits;
    return "";
  }

  function normalizeEmail(raw) {
    return raw ? raw.toString().trim().toLowerCase() : "";
  }

  function normalizeName(raw) {
    return raw ? raw.toString().trim().toLowerCase().replace(/\s+/g, " ") : "";
  }

  function parseTimestamp(val) {
    if (!val) return null;
    if (val instanceof Date) return val;
    const d = new Date(val);
    return isNaN(d.getTime()) ? null : d;
  }

  function withinMinutes(ts1, ts2, minutes) {
    if (!ts1 || !ts2) return false;
    return Math.abs(ts1.getTime() - ts2.getTime()) <= minutes * 60 * 1000;
  }

  function completenessScore(row) {
    const fields = [
      row[COL.joinedBefore],
      normalizePhone(row[COL.phone]),
      row[COL.park],
      normalizeEmail(row[COL.email]),
    ];
    return fields.filter(f => f && f.toString().trim() !== "" && f.toString().trim() !== "REVIEW").length;
  }

  function getConflicts(rows) {
    const fieldNames = ["JoinedBefore", "Phone", "PreferredPark", "Email"];
    const getters = [
      r => r[COL.joinedBefore],
      r => normalizePhone(r[COL.phone]),
      r => r[COL.park],
      r => normalizeEmail(r[COL.email]),
    ];
    const conflicting = [];
    fieldNames.forEach((name, i) => {
      const values = rows.map(r => (getters[i](r) || "").toString().trim().toLowerCase());
      const unique = [...new Set(values.filter(v => v !== "" && v !== "review"))];
      if (unique.length > 1) conflicting.push(name);
    });
    return conflicting.join(", ");
  }

  // ── Build row objects (skip header) ──────────────────────────────────────

  const rows = data.slice(1).map((row, i) => ({
    rowIndex: i + 1,          // 0-based index into data array
    sheetRow: i + 2,          // 1-based sheet row number
    data: row,
    email: normalizeEmail(row[COL.email]),
    name: normalizeName(row[COL.name]),
    timestamp: parseTimestamp(row[COL.timestamp_c]) || parseTimestamp(row[COL.timestamp]),
    score: 0,
    groupId: null,
  }));

  rows.forEach(r => { r.score = completenessScore(r.data); });

  // ── Group rows by email or name+timestamp proximity ───────────────────────

  let nextGroupId = 0;

  function mergeGroups(a, b) {
    if (a.groupId === null && b.groupId === null) {
      a.groupId = b.groupId = nextGroupId++;
    } else if (a.groupId === null) {
      a.groupId = b.groupId;
    } else if (b.groupId === null) {
      b.groupId = a.groupId;
    } else if (a.groupId !== b.groupId) {
      const old = b.groupId;
      rows.forEach(r => { if (r.groupId === old) r.groupId = a.groupId; });
    }
  }

  for (let i = 0; i < rows.length; i++) {
    for (let j = i + 1; j < rows.length; j++) {
      const a = rows[i], b = rows[j];
      const sameEmail = a.email && b.email && a.email === b.email;
      const sameName = a.name && b.name && a.name === b.name;
      const closeTime = withinMinutes(a.timestamp, b.timestamp, 10);
      if (sameEmail || (sameName && closeTime)) mergeGroups(a, b);
    }
  }

  // ── Decide winner per group, write output ────────────────────────────────

  const groups = {};
  rows.forEach(r => {
    if (r.groupId !== null) {
      if (!groups[r.groupId]) groups[r.groupId] = [];
      groups[r.groupId].push(r);
    }
  });

  // Prepare a batch of output values indexed by sheetRow.
  const output = {};
  rows.forEach(r => {
    output[r.sheetRow] = {
      cleanedJoined:    r.data[COL.joinedBefore] || "",
      cleanedPhone:     normalizePhone(r.data[COL.phone]),
      cleanedTimestamp: r.data[COL.timestamp_c] || "",
      cleanedPark:      r.data[COL.park] || "",
      superseded:       "",
      conflicts:        "",
    };
  });

  Object.values(groups).forEach(group => {
    group.sort((a, b) => b.score - a.score);
    const winner = group[0];
    const conflicts = getConflicts(group.map(r => r.data));

    group.forEach(r => {
      output[r.sheetRow].conflicts = conflicts;
      if (r.sheetRow !== winner.sheetRow) {
        output[r.sheetRow].superseded = "SUPERSEDED";
        output[r.sheetRow].cleanedJoined    = winner.data[COL.joinedBefore] || "";
        output[r.sheetRow].cleanedPhone     = normalizePhone(winner.data[COL.phone]);
        output[r.sheetRow].cleanedTimestamp = winner.data[COL.timestamp_c] || "";
        output[r.sheetRow].cleanedPark      = winner.data[COL.park] || "";
      }
    });
  });

  // ── Write output in one batch ─────────────────────────────────────────────

  rows.forEach(r => {
    const o = output[r.sheetRow];
    sheet.getRange(r.sheetRow, OUT.cleanedJoined + 1, 1, 6).setValues([[
      o.cleanedJoined,
      o.cleanedPhone,
      o.cleanedTimestamp,
      o.cleanedPark,
      o.superseded,
      o.conflicts,
    ]]);
  });

  SpreadsheetApp.getUi().alert("Done. Check columns Q–V for cleaned values, Superseded, and Conflicts.");
}
```

---

**How to use it**

1. Open **Extensions > Apps Script**, paste the whole thing, save, and run `cleanVolunteerData`.
2. Put your default area code (e.g., `555`) in cell **Z1** before running. Leave it blank if you don't want 7-digit phones auto-expanded.
3. The script writes six new columns starting at **Q**: CleanedJoined, CleanedPhone, CleanedTimestamp, CleanedPark, Superseded, and Conflicts.
4. Superseded rows get the winner's cleaned values copied in, so you have one consistent version of each group even before you delete anything.

**A few things worth knowing**

The grouping loop is O(n²), which is fine for 420 rows but would slow down above ~5,000. The score tiebreaker is currently "first row wins among equals" — if you'd rather keep the most recent submission, add a secondary sort on `r.timestamp` descending inside the `group.sort` call. The COL and OUT objects at the top are the only things you'd need to change if your column layout differs.

```javascript
function cleanAndExport() {
  let TIME_WINDOW_MIN = 10; // default; may be overridden by prompt below

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const raw = ss.getSheetByName('Raw');
  if (!raw) throw new Error('Sheet "Raw" not found.');

  // Optional interactive prompt.
  try {
    const ui = SpreadsheetApp.getUi();
    const resp = ui.prompt(
      'Time window (minutes)',
      `Confirm or change the name+time duplicate window. Default: ${TIME_WINDOW_MIN}`,
      ui.ButtonSet.OK_CANCEL
    );
    if (resp.getSelectedButton() === ui.Button.OK) {
      const n = Number(resp.getResponseText().trim());
      if (!isNaN(n) && n > 0) TIME_WINDOW_MIN = n;
    }
  } catch (e) { /* no UI, keep default */ }

  const lastRow = raw.getLastRow();
  if (lastRow < 2) return;

  const sheetLastCol = raw.getLastColumn();
  const lastCol = Math.max(sheetLastCol, 16);

  // Column map (1-based):
  // 1=A Timestamp, 2=B Name, 3=C Email, 4=D JoinedBefore, 5=E Phone,
  // 6=F PreferredPark, 7=G YN_clean, 8=H Phone_clean, 9=I TS_clean,
  // 10=J Park_clean, 11=K emailKey, 12=L nameKey, 13=M DUP-email,
  // 14=N DUP-name-time, 15=O Superseded, 16=P Review
  const COL = {
    TS_CLEAN: 9, EMAIL_KEY: 11, NAME_KEY: 12,
    SUPERSEDED: 15, REVIEW: 16,
    REVIEW_SOURCES: [7, 8, 9, 10],
  };

  const numRows = lastRow - 1;

  const padRow = (row, n) =>
    row.length >= n ? row : row.concat(new Array(n - row.length).fill(''));

  const headers = padRow(raw.getRange(1, 1, 1, sheetLastCol).getValues()[0], lastCol);
  const data = raw.getRange(2, 1, numRows, sheetLastCol).getValues()
    .map(r => padRow(r, lastCol));

  const tsNum = v => {
    if (v instanceof Date) return v.getTime();
    if (typeof v === 'number' && !isNaN(v)) {
      return Math.round((v - 25569) * 86400 * 1000);
    }
    return NaN;
  };

  const windowMs = TIME_WINDOW_MIN * 60 * 1000;

  // Capture prior SUPERSEDED values so we can count NEW ones later
  const priorSuperseded = data.map(r => String(r[COL.SUPERSEDED - 1] || ''));

  // --- Step 1a: SUPERSEDED by email ---
  const latestByEmail = {};
  data.forEach((row, i) => {
    const key = String(row[COL.EMAIL_KEY - 1] || '').trim();
    const t = tsNum(row[COL.TS_CLEAN - 1]);
    if (!key || isNaN(t)) return;
    if (!latestByEmail[key] || t > latestByEmail[key].ts) {
      latestByEmail[key] = { ts: t, rowIdx: i };
    }
  });

  const supersededOut = data.map(r => [r[COL.SUPERSEDED - 1]]);

  data.forEach((row, i) => {
    const key = String(row[COL.EMAIL_KEY - 1] || '').trim();
    const t = tsNum(row[COL.TS_CLEAN - 1]);
    if (!key || isNaN(t)) return;
    const latest = latestByEmail[key];
    supersededOut[i][0] = (latest && i !== latest.rowIdx) ? 'SUPERSEDED' : '';
  });

  // --- Step 1b: SUPERSEDED by nameKey + time window (no-email rows) ---
  const noEmailByName = {};
  data.forEach((row, i) => {
    const email = String(row[COL.EMAIL_KEY - 1] || '').trim();
    if (email) return;
    const name = String(row[COL.NAME_KEY - 1] || '').trim();
    const t = tsNum(row[COL.TS_CLEAN - 1]);
    if (!name || isNaN(t)) return;
    (noEmailByName[name] = noEmailByName[name] || []).push({ ts: t, rowIdx: i });
  });

  Object.values(noEmailByName).forEach(entries => {
    if (entries.length < 2) return;
    entries.sort((a, b) => a.ts - b.ts);
    const used = new Set();
    for (let a = 0; a < entries.length; a++) {
      if (used.has(a)) continue;
      const cluster = [entries[a]];
      for (let b = a + 1; b < entries.length; b++) {
        if (used.has(b)) continue;
        if (entries[b].ts - cluster[cluster.length - 1].ts <= windowMs) {
          cluster.push(entries[b]);
        }
      }
      if (cluster.length > 1) {
        const keeperRow = cluster[cluster.length - 1].rowIdx;
        cluster.forEach(e => {
          used.add(entries.indexOf(e));
          if (e.rowIdx !== keeperRow) supersededOut[e.rowIdx][0] = 'SUPERSEDED';
        });
      } else {
        used.add(a);
      }
    }
  });

  raw.getRange(2, COL.SUPERSEDED, numRows, 1).setValues(supersededOut);

  // Count NEWLY superseded: now SUPERSEDED but wasn't before
  const newlySupersededCount = supersededOut.reduce((acc, r, i) =>
    acc + ((r[0] === 'SUPERSEDED' && priorSuperseded[i] !== 'SUPERSEDED') ? 1 : 0), 0);

  // --- Step 2: Batch-fill P where blank and no formula ---
  const pRange = raw.getRange(2, COL.REVIEW, numRows, 1);
  const pValues = pRange.getValues();
  const pFormulas = pRange.getFormulas();

  let newReviewWrites = 0;
  const pOut = pValues.map((cell, i) => {
    const hasFormula = pFormulas[i][0] !== '';
    const hasValue = cell[0] !== '' && cell[0] !== null;
    if (hasFormula) return [pFormulas[i][0]];
    if (hasValue) return [cell[0]];
    const anyReview = COL.REVIEW_SOURCES.some(c => String(data[i][c - 1]) === 'REVIEW');
    if (anyReview) {
      newReviewWrites++;
      return ['REVIEW'];
    }
    return [''];
  });

  const valueOut = pOut.map(c => [typeof c[0] === 'string' && c[0].startsWith('=') ? '' : c[0]]);
  const formulaOut = pOut.map(c => [typeof c[0] === 'string' && c[0].startsWith('=') ? c[0] : '']);
  pRange.setValues(valueOut);
  pRange.setFormulas(formulaOut);

  // --- Step 3: Rebuild "Final" ---
  const finalData = raw.getRange(2, 1, numRows, lastCol).getValues()
    .map(r => padRow(r, lastCol));
  const keep = finalData.filter(r =>
    String(r[COL.REVIEW - 1]) === 'OK' && String(r[COL.SUPERSEDED - 1]) === ''
  );

  let finalSheet = ss.getSheetByName('Final');
  if (!finalSheet) {
    finalSheet = ss.insertSheet('Final');
  } else {
    finalSheet.clearContents();
  }
  finalSheet.getRange(1, 1, 1, lastCol).setValues([headers]);
  if (keep.length) {
    finalSheet.getRange(2, 1, keep.length, lastCol).setValues(keep);
  }

  const supersededCount = supersededOut.filter(r => r[0] === 'SUPERSEDED').length;

  // Runner email, blank if unavailable
  let runnerEmail = '';
  try { runnerEmail = Session.getActiveUser().getEmail() || ''; } catch (e) { runnerEmail = ''; }

  // --- Step 4: Append to Logs sheet ---
  let logs = ss.getSheetByName('Logs');
  if (!logs) {
    logs = ss.insertSheet('Logs');
    logs.getRange(1, 1, 1, 8).setValues([[
      'Run timestamp', 'Runner email', 'Rows processed',
      'Superseded (total)', 'Superseded (new this run)',
      'P newly set to REVIEW', 'Exported to Final', 'TIME_WINDOW_MIN'
    ]]);
  }
  logs.appendRow([
    new Date(), runnerEmail, numRows,
    supersededCount, newlySupersededCount,
    newReviewWrites, keep.length, TIME_WINDOW_MIN
  ]);

  try {
    SpreadsheetApp.getActive().toast(
      `Final: ${keep.length}. Superseded total/new: ${supersededCount}/${newlySupersededCount}. ` +
      `P→REVIEW new: ${newReviewWrites}. Window: ${TIME_WINDOW_MIN} min.`
    );
  } catch (e) { /* no UI, skip toast */ }
}
```

**What changed:**

- **Runner email.** `Session.getActiveUser().getEmail()` is wrapped in try/catch and defaults to `''`. Note that in many script contexts (e.g., when the script is run by a user other than the file owner, or from certain triggers) this legitimately returns an empty string — that's a Google policy, not a bug.
- **Newly superseded count.** Captured `priorSuperseded` from the sheet before writing, then counted rows where the new value is `SUPERSEDED` but the prior wasn't.
- **New P→REVIEW writes.** Incremented a counter inside the P-build loop only when a previously blank, formula-less P cell is being set to `'REVIEW'` this run.
- **Logs header** expanded to 8 columns. On existing Logs sheets from the previous version (5 columns), new runs will still append correctly — the new row will just extend into columns F–H without re-writing the header. If you want the header auto-upgraded on first run after this change, delete the Logs sheet once and let the script recreate it.
